Lemma w4s_end : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (r3 r4 r5 r6 r7 r8 r10 r12 r15 r17 r18 r19 r20 r21 r22 r23 r24 r25 r26 r27 r29 r30 r31 : word)
    (P O4Q Q0 OL ST1 ST2 ST3 ST4 : Z),
  (ST1 = 0 \/ ST1 = 3) -> (ST2 = 0 \/ ST2 = 3) -> (ST3 = 0 \/ ST3 = 3) -> (ST4 = 0 \/ ST4 = 3) ->
  0 <= O4Q < 2^47 -> 0 <= Q0 < 2^47 -> 0 <= OL < 2^47 ->
  (O4Q + 4 < OL -> ST1 = 0 -> ST2 = 0 -> ST3 = 0 -> ST4 = 0 -> forall (y11 y12 : word),
     evtF asegs RNG Q (MS (mkR (Z_to_bv 64 OL) (Z_to_bv 64 P) r3 r4 r5 r6 r7 r8 (Z_to_bv 64 (O4Q + 4)) r10 y11 y12
                              (Z_to_bv 64 ST1) (Z_to_bv 64 ST4) r15 (Z_to_bv 64 ST3) r17 r18 r19 r20 r21 r22 r23 r24 r25 r26
                              r27 (Z_to_bv 64 (Q0 + 4)) r29 r30 r31) F (Z_to_bv 64 0x90cc0) fc None mm (seg_rom asegs))) ->
  ((OL <= O4Q + 4 \/ ST1 <> 0 \/ ST2 <> 0 \/ ST3 <> 0 \/ ST4 <> 0) -> forall (y11 y12 : word),
     evtF asegs RNG Q (MS (mkR (Z_to_bv 64 OL) (Z_to_bv 64 P) r3 r4 r5 r6 r7 r8 (Z_to_bv 64 (O4Q + 4)) r10 y11 y12
                              (Z_to_bv 64 ST1) (Z_to_bv 64 ST4) r15 (Z_to_bv 64 ST3) r17 r18 r19 r20 r21 r22 r23 r24 r25 r26
                              r27 (Z_to_bv 64 (Q0 + 4)) r29 r30 r31) F (Z_to_bv 64 0x91810) fc None mm (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR (Z_to_bv 64 OL) (Z_to_bv 64 P) r3 r4 r5 r6 r7 r8 (Z_to_bv 64 O4Q) r10 (Z_to_bv 64 ST2) r12
                           (Z_to_bv 64 ST1) (Z_to_bv 64 ST4) r15 (Z_to_bv 64 ST3) r17 r18 r19 r20 r21 r22 r23 r24 r25 r26 r27
